	public const string Style = "/* UI1: shared surfaces use the owner's existing theme, accent and density tokens. */\nbody.suiteThemed #app section{--bg:var(--suite-bg);--panel:var(--suite-panel);--text:var(--suite-text)}\n#app section{--ui-inset:color-mix(in srgb,var(--panel) 84%,var(--bg));--ui-soft:color-mix(in srgb,var(--accent) 8%,var(--panel))}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .pageTitle{padding-bottom:14px;border-bottom:1px solid var(--line);margin-bottom:18px}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .card{box-shadow:0 4px 16px #00000012;background:var(--panel);border-color:var(--line)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .cardHeader{gap:10px;align-items:center;flex-wrap:wrap}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) h3{font-size:14px;letter-spacing:.01em}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .tableWrap{border:1px solid var(--line);border-radius:8px}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) th{background:var(--ui-inset);font-size:11px;letter-spacing:.03em}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) td{font-variant-numeric:tabular-nums;vertical-align:top}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) tbody tr:nth-child(even){background:color-mix(in srgb,var(--text) 2%,transparent)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) tbody tr:hover{background:var(--ui-soft)}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .compactNote{background:var(--ui-inset);border:1px solid var(--line);color:var(--muted);line-height:1.65}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#customPatches) .toolbar{gap:8px;align-items:center}\n#app :is(#admin,#roles,#profiler,#anticheat,#databaseStorage,#custo