	public const string Script = "// Local view state only: switching tabs never fetches inventories or mutates settings.\nfunction uiInstallTabs(host,entries,key,before,onChange=()=>{}){\n const nav=document.createElement('div');nav.className='uiTabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label',key==='player'?'Selected player views':'Profiler views');\n let selected=entries[0].key;try{const saved=localStorage.getItem('nsu.ui1.'+key);if(entries.some(e=>e.key===saved))selected=saved;}catch{}\n for(const entry of entries){const button=document.createElement('button');button.type='button';button.dataset.uiTab=key+':'+entry.key;button.id='ui1-'+key+'-'+entry.key;button.textContent=entry.label;button.setAttribute('role','tab');\n  entry.nodes.filter(Boolean).forEach((node,index)=>{node.dataset.uiPane=key+':'+entry.key;node.setAttribute('role','tabpanel');node.setAttribute('aria-labelledby',button.id);if(!node.id)node.id='ui1-'+key+'-'+entry.key+'-pane-'+index;});\n  button.setAttribute('aria-controls',entry.nodes.filter(Boolean).map(n=>n.id).join(' '));button.onclick=()=>select(entry.key);nav.append(button);\n }\n function select(value){selected=value;for(const entry of entries){const active=entry.key===value;const b=nav.querySelector('[data-ui-tab=\"'+key+':'+entry.key+'\"]');b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;entry.nodes.filter(Boolean).forEach(node=>node.hidden=!active);}try{localStorage.setItem('nsu.ui1.'+key,value);}catch{}onChange(value);if(typeof syncWorkspacePage==='function')syncWorkspacePage();}\n nav.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const buttons=[...nav.querySelectorAll('button')],at=entries.findIndex(x=>x.key===selected),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;buttons[next].click();buttons[next].focus();};\n host.insertBefore(nav,before||null);select(selected);return {select,nav};\n}\nfunction uiRefreshTable(id){\n enhanceTableByBodyId(id);const body=$(id),wrap=body?.closest('.tableWrap');if(!wrap)return;\n const filter=wrap.previousElementSibling?.querySelector('.tableTools input,input');if(filter)filter.dispatchEvent(new Event('input'));\n const sorted=body.closest('table').querySelector('th[data-sort-dir]');if(sorted){const dir=sorted.dataset.sortDir;sorted.dataset.sortDir=dir==='asc'?'desc':'asc';sorted.click();}\n}\nfunction uiMarkSelectedPlayer(){\n document.querySelectorAll('#adminPlayerRows tr').forEach(row=>{row.classList.toggle('uiSelectedPlayer',row.dataset.uiPlayer===adminSelectedPlayer);});\n}\nfunction uiInitPlayerViews(){\n const host=$('adminPlayerDetail'),identity=$('adminPlayerTitle').closest('.card'),investigation=$('investigationLoad').closest('.card');identity.classList.add('uiIdentity');host.prepend(identity);\n const notes=$('adminWarningRows').closest('.grid'),inventory=$('adminInventoryGrid').closest('.card'),history=$('adminHistoryRows').closest('.card');\n uiInstallTabs(host,[{key:'overview',label:'Notes & warnings',nodes:[notes]},{key:'investigation',label:'Investigation',nodes:[investigation]},{key:'inventory',label:'Inventory',nodes:[inventory]},{key:'history',label:'Player history',nodes:[history]}],'player',identity.nextSibling);\n const actions=$('adminWarn').parentElement,groups=document.createElement('div');groups.className='uiActionGroups';\n const definitions=[['Moderation',['adminWarn','adminMute','adminUnmute','adminKick']],['Restrictions',['adminTempBan','adminUnban','adminFreeze','adminUnfreeze','adminJail','adminUnjail']],['Player recovery',['adminHeal','adminFeed','adminRevive','adminSmite','adminSendBack','adminAllowCharSelOnce']],['Staff records',['adminAddNote','adminCopyPlayer']]];\n for(const [label,ids] of definitions){const field=document.createElement('fieldset'),legend=document.createElement('legend'),row=document.createElement('div');field.className='uiActionGroup';row.className='quickActions';legend.textContent=label;field.append(legend,row);ids.forEach(id=>{if($(id))row.append($(id));});groups.append(field);}actions.replaceWith(groups);\n const select=selectAdminPlayer;selectAdminPlayer=async(...args)=>{await select(...args);uiMarkSelectedPlayer();};\n const render=renderAdminPlayerList;renderAdminPlayerList=(...args)=>{render(...args);uiMarkSelectedPlayer();};\n}\nfunction uiInitRoleGroups(){\n const form=$('roleEditor'),grid=form.querySelector('.grid2'),minima=$('roleClaimX').closest('.row');\n function fieldGroup(label){const box=document.createElement('fieldset'),legend=document.createElement('legend');box.className='uiFieldGroup';legend.textContent=label;box.append(legend);form.insertBefore(box,grid);return box;}\n const identity=fieldGroup('Identity & appearance'),identityGrid=document.createElement('div');identityGrid.className='grid2';identity.append(identityGrid);\n ['roleCode','roleName','roleDescription','roleRank','roleColor','roleNameColor','roleGameMode'].forEach(id=>identityGrid.append($(id).closest('.field')));\n identity.append($('roleUseColors').closest('.toggleLine'));\n const limits=fieldGroup('Homes & land claims'),limitsGrid=document.createElement('div');limitsGrid.className='grid2';limits.append(limitsGrid);['roleHomeLimit','roleClaimAllowance','roleClaimAreas'].forEach(id=>limitsGrid.append($(id).closest('.field')));limits.append(minima);\n const permissions=fieldGroup('Permissions'),tools=document.createElement('div');tools.className='uiPermissionTools';\n const category=document.createElement('select');category.id='uiPrivilegeCategory';category.setAttribute('aria-label','Privilege category');category.innerHTML='<option value=\"all\">All permissions</option><option value=\"selected\">Granted permissions</option><option value=\"administration\">Administration</option><option value=\"world\">World & building</option><option value=\"other\">Other / mod permissions</option>';\n const count=document.createElement('span');count.id='uiPrivilegeCount';count.className='small';count.setAttribute('role','status');\n const heading=$('rolePrivilegeSearch').previousElementSibling;if(heading?.classList.contains('small'))permissions.append(heading);\n tools.append($('rolePrivilegeSearch'),category,count);permissions.append(tools,$('roleAutoGrant').closest('.toggleLine'),$('rolePrivilegeList'),$('roleExtraPrivileges').closest('.field'),$('roleRuntimePrivileges'));\n const travel=fieldGroup('Teleport access & cooldowns');travel.append($('rolePolicyNote'),$('rolePolicies'));\n grid.remove();form.querySelectorAll(':scope > h3').forEach(h=>h.remove());$('roleSave').closest('.toolbar').classList.add('uiRoleFooter');\n const changes=document.createElement('details');changes.id='uiRoleChanges';changes.className='uiDraftChanges';changes.hidden=true;form.insertBefore(changes,$('roleSave').closest('.toolbar'));\n const rail=$('roleList').closest('.card');rail.classList.add('uiRoleRail');const railTools=document.createElement('div');railTools.className='toolbar';railTools.append($('roleSearch'),$('rolesReload'));rail.prepend(railTools);\n [identity,limits,permissions,travel].forEach((box,index)=>{const legend=box.querySelector('legend'),label=legend.textContent,content=document.createElement('div');content.id='uiRoleGroupBody'+index;[...box.children].filter(n=>n!==legend).forEach(n=>content.append(n));box.append(content);const toggle=document.createElement('button');toggle.type='button';toggle.className='uiGroupToggle';toggle.dataset.uiFold=String(index);toggle.textContent=label;toggle.setAttribute('aria-controls',content.id);legend.replaceChildren(toggle);let folded=false;try{folded=localStorage.getItem('nsu.ui1.roleGroup.'+index)==='closed';}catch{}function setFold(value){folded=value;content.hidden=value;toggle.setAttribute('aria-expanded',String(!value));}setFold(folded);toggle.onclick=()=>{setFold(!folded);try{localStorage.setItem('nsu.ui1.roleGroup.'+index,folded?'closed':'open');}catch{}};}